const inItem = $input.first().json;
const body = (inItem && inItem.body) ? inItem.body : inItem;
function norm(s){ if(s===undefined||s===null) return ""; return String(s).toLowerCase().trim(); }
function num(s){ const n = Number(s); return isFinite(n) ? n : 0; }

const DISC = "Indikativer Richtwert, kein verbindliches Angebot. Das offizielle Angebot erhalten Sie per E-Mail.";

const CATALOG = {
  car: [
    { ProductCode:"CAR-LIAB-STD", ProductName:"Unica Kfz Haftpflicht", base:480 },
    { ProductCode:"CAR-TK-COMFORT", ProductName:"Unica Kfz Komfort (Haftpflicht + Teilkasko)", base:760 },
    { ProductCode:"CAR-VK-PREMIUM", ProductName:"Unica Kfz Premium (Haftpflicht + Vollkasko)", base:1180 }
  ],
  liability: [
    { ProductCode:"LIAB-SINGLE", ProductName:"Unica Privathaftpflicht Single", base:70 },
    { ProductCode:"LIAB-FAMILY", ProductName:"Unica Privathaftpflicht Familie", base:95 }
  ],
  home_contents: [
    { ProductCode:"HC-STD", ProductName:"Unica Haushalt Standard", rate:0.0016 },
    { ProductCode:"HC-PLUS", ProductName:"Unica Haushalt Plus", rate:0.0022 }
  ],
  legal: [
    { ProductCode:"LEGAL-PRIVATE", ProductName:"Unica Rechtsschutz Privat", base:230 },
    { ProductCode:"LEGAL-COMBO", ProductName:"Unica Rechtsschutz Kombi", base:360 }
  ],
  life: [
    { ProductCode:"LIFE-TERM-STD", ProductName:"Unica Risikoleben", rate:0.0009 },
    { ProductCode:"LIFE-VORSORGE", ProductName:"Unica Leben Vorsorge", rate:0.0021 }
  ]
};

function mapLine(raw){
  const s = norm(raw);
  function has(arr){ for(var i=0;i<arr.length;i++){ if(s.indexOf(arr[i])>=0) return true; } return false; }
  if(has(["car","auto","kfz","pkw","fahrzeug","automobil"])) return "car";
  if(has(["haftpflicht","liability"])) return "liability";
  if(has(["hausrat","haushalt","home","contents","eigenheim","wohnung","inhalt"])) return "home_contents";
  if(has(["rechtsschutz","legal","recht"])) return "legal";
  if(has(["leben","life","vorsorge","risikoleben"])) return "life";
  return "";
}

function round10(n){ var r = Math.round(n/10)*10; return r < 10 ? 10 : r; }
function band(mid){ return { low: round10(mid*0.82), high: round10(mid*1.18), currency:"EUR", per:"year" }; }
function pick(line, code){ var arr = CATALOG[line]; for(var i=0;i<arr.length;i++){ if(arr[i].ProductCode===code) return arr[i]; } return arr[0]; }

const line = mapLine(body.line_of_business);

if(!line){
  return [{ json: {
    status:"Disqualified",
    line: norm(body.line_of_business) || "unknown",
    recommended_product: null,
    indicative_range: null,
    rationale: "Diese Versicherungsart wird aktuell nicht angeboten. Ich leite Sie an einen Spezialisten weiter, der zurueckruft.",
    missing_fields: [],
    next_step: "pass_to_specialist",
    disclaimer: DISC
  } }];
}

var prod = null;
var mid = 0;
var missing = [];
var rationale = "";

if(line === "car"){
  var cov = norm(body.coverage);
  var age = num(body.driver_age);
  if(!cov) missing.push("coverage");
  if(!age) missing.push("driver_age");
  if(missing.length === 0){
    var code = "CAR-LIAB-STD";
    if(cov.indexOf("vollkasko")>=0 || cov.indexOf("voll")>=0) code = "CAR-VK-PREMIUM";
    else if(cov.indexOf("teilkasko")>=0 || cov.indexOf("teil")>=0) code = "CAR-TK-COMFORT";
    prod = pick("car", code);
    var power = num(body.power_kw); if(!power) power = 70;
    var region = norm(body.region);
    var bm = num(body.bonus_malus); if(!bm) bm = 1.0;
    var ageF = 1.0;
    if(age<25) ageF=1.30; else if(age<30) ageF=1.18; else if(age<40) ageF=1.05; else if(age<60) ageF=1.0; else if(age<70) ageF=1.15; else ageF=1.35;
    var powerF = 1 + Math.max(0,(power-70))*0.006;
    var regionF = (region.indexOf("wien")>=0)?1.15:((region.indexOf("graz")>=0||region.indexOf("linz")>=0)?1.07:1.0);
    mid = prod.base * ageF * powerF * regionF * bm;
    rationale = prod.ProductName + " passend fuer Fahrer mit " + age + " Jahren.";
  }
} else if(line === "liability"){
  var hh = norm(body.household);
  var lcode = (hh.indexOf("famil")>=0) ? "LIAB-FAMILY" : "LIAB-SINGLE";
  prod = pick("liability", lcode);
  mid = prod.base;
  rationale = prod.ProductName + " passend.";
} else if(line === "home_contents"){
  var cv = num(body.contents_value);
  if(!cv){ missing.push("contents_value"); }
  else {
    var hcov = norm(body.coverage);
    var hcode = (hcov.indexOf("plus")>=0 || hcov.indexOf("premium")>=0) ? "HC-PLUS" : "HC-STD";
    prod = pick("home_contents", hcode);
    var hregion = norm(body.region);
    var hregF = (hregion.indexOf("wien")>=0)?1.10:1.0;
    mid = cv * prod.rate * hregF;
    rationale = prod.ProductName + " fuer Versicherungssumme " + cv + " Euro.";
  }
} else if(line === "legal"){
  var lcov = norm(body.coverage);
  var legcode = (lcov.indexOf("kombi")>=0 || lcov.indexOf("combo")>=0 || lcov.indexOf("verkehr")>=0) ? "LEGAL-COMBO" : "LEGAL-PRIVATE";
  prod = pick("legal", legcode);
  mid = prod.base;
  rationale = prod.ProductName + " passend.";
} else if(line === "life"){
  var sa = num(body.sum_assured);
  if(!sa){ missing.push("sum_assured"); }
  else {
    var vcov = norm(body.coverage);
    var vcode = (vcov.indexOf("vorsorge")>=0 || vcov.indexOf("spar")>=0 || vcov.indexOf("erleben")>=0) ? "LIFE-VORSORGE" : "LIFE-TERM-STD";
    prod = pick("life", vcode);
    var term = num(body.term_years); if(!term) term = 15;
    var tobRaw = norm(body.tobacco);
    var tob = (body.tobacco===true || tobRaw.indexOf("ja")>=0 || tobRaw.indexOf("yes")>=0 || tobRaw.indexOf("rauch")>=0 || tobRaw.indexOf("smok")>=0);
    var tobF = tob ? 1.6 : 1.0;
    var termF = 1 + Math.max(0,(term-10))*0.015;
    mid = sa * prod.rate * tobF * termF;
    rationale = prod.ProductName + " fuer Versicherungssumme " + sa + " Euro, Laufzeit " + term + " Jahre.";
  }
}

if(missing.length > 0){
  return [{ json: {
    status:"NeedsReview",
    line: line,
    recommended_product: prod ? { ProductCode: prod.ProductCode, ProductName: prod.ProductName } : null,
    indicative_range: null,
    rationale: "Es fehlen noch Angaben fuer die Schaetzung.",
    missing_fields: missing,
    next_step: "collect_missing",
    disclaimer: DISC
  } }];
}

var rng = band(mid);
return [{ json: {
  status:"Qualified",
  line: line,
  recommended_product: { ProductCode: prod.ProductCode, ProductName: prod.ProductName },
  indicative_range: rng,
  rationale: rationale,
  missing_fields: [],
  next_step: "offer_consultation_booking",
  disclaimer: DISC
} }];
